int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    vector<double> a(n);
    for (int i = 0; i < n; ++i) {
        scanf("%lf", &a[i]);
    }
    int count_zero = 0;
    for (double val : a) {
        if (val < 1e-10) ++count_zero;
    }
    k = min(n - count_zero, k);
    vector<double> p(1 << n, 0.0), res(n, 0.0);
    p[0] = 1.0;
    for (int mask = 1; mask < (1 << n); ++mask) {
        double sum_a = 0.0;
        bool valid = true;
        int bits_count = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                sum_a += a[i];
                if (a[i] < 1e-10) valid = false;
                ++bits_count;
            }
        }
        if (!valid) {
            p[mask] = 0.0;
            continue;
        }
        double sum_prob = 0.0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                double denom = 1.0 - sum_a + a[i];
                sum_prob += (a[i] / denom) * p[mask ^ (1 << i)];
            }
        }
        p[mask] = sum_prob;
        if (bits_count == k) {
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    res[i] += p[mask];
                }
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        printf("%.10f%c", res[i], (i == n - 1) ? '\n' : ' ');
    }
    return 0;
