import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] a = new double[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextDouble();
        }
        int count_zero = 0;
        for (double val : a) {
            if (val < 1e-10) {
                count_zero++;
            }
        }
        k = Math.min(n - count_zero, k);
        int size = 1 << n;
        double[] p = new double[size];
        double[] res = new double[n];
        p[0] = 1.0;
        for (int mask = 1; mask < size; mask++) {
            double sum_a = 0.0;
            boolean valid = true;
            int bits_count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum_a += a[i];
                    if (a[i] < 1e-10) {
                        valid = false;
                    }
                    bits_count++;
                }
            }
            if (!valid) {
                p[mask] = 0.0;
                continue;
            }
            double sum_prob = 0.0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    double denom = 1.0 - sum_a + a[i];
                    sum_prob += (a[i] / denom) * p[mask ^ (1 << i)];
                }
            }
            p[mask] = sum_prob;
            if (bits_count == k) {
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        res[i] += p[mask];
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            System.out.printf("%.10f%c", res[i], (i == n - 1) ? '\n' : ' ');
        }
        sc.close();
    }
}
